run('mi_getmaterial', 'newdocument(0)\nmi_probdef(0, \'millimeters\', \'planar\', 1e-8, 10, 30, 0)\ngood = [\'Air\', \'Copper\', \'N30\', \'N33\', \'N35\', \'N38\', \'N40\', \'N42\', \'N45\', \'N48\', \'N50\', \'N52\', \'N55\', \'SmCo18(1:5)\', \'SmCo24\', \'SmCo28\', \'SmCo32\', \'Ceramic 5\', \'Ceramic 8A\', \'Ceramic 8B\', \'Y30\', \'Y35\', \'BN1\', \'BN10\', \'Cast Alnico 5 (LNG37)\', \'Sintered Alnico 5 (FLNG34)\', \'M-15 14 mil\', \'M-19 14 mil\', \'M-22 14 mil\', \'M-27 14 mil\', \'M-36 14 mil\', \'M-43 18 mil\', \'M-47 18 mil\', \'M-19\', \'M-27\', \'M-50\', \'M-43 and M-36\', \'ARMCO Pure Iron\', \'Pure iron, annealed\', \'1006 Steel (hot rolled)\', \'1010 Steel (hot rolled)\', \'1018 Steel (hot rolled)\', \'1020 Steel (hot rolled)\', \'Hot rolled low-carbon steel\', \'Supermendur\', \'Vanadium Permendur\', \'CoFe 49Co-2V, rotor grade\', \'CoFe 49Co-2V, magnetic anneal\', \'Metglas 2605SA1, field annealed\', \'Mumetal\', \'Stainless 430F, annealed\', \'304 Stainless Steel\', \'316 Stainless Steel\', \'Aluminum, 1100\', \'Aluminum, 6061-T6\', \'10 AWG\', \'12 AWG\', \'14 AWG\', \'16 AWG\', \'18 AWG\', \'20 AWG\', \'22 AWG\', \'24 AWG\', \'26 AWG\', \'28 AWG\', \'30 AWG\', \'32 AWG\', \'34 AWG\', \'36 AWG\', \'18 SWG\', \'40 SWG\', \'0.125mm\', \'0.16mm\', \'0.2mm\', \'0.25mm\', \'0.315mm\', \'0.4mm\', \'0.5mm\', \'0.63mm\', \'0.8mm\', \'1mm\', \'1.25mm\', \'1.6mm\', \'2mm\', \'2.5mm\', \'18AWG 15% CCA\']\nbad = [\'Pure Iron\', \'1010 Steel\', \'M-19 Steel\', \'M-27 Steel\', \'M-36 Steel\', \'NdFeB 32 MGOe\', \'NdFeB 40 MGOe\', \'Alnico 5\', \'Ceramic 8\', \'SmCo 24 MGOe\', \'Hiperco-50\', \'Hiperco 50\', \'M-400-50A\', \'35JN270\', \'19 AWG\', \'copper\', \'NoSuchMaterial\']\nfirst = mi_getmaterial(good[0])\nfor name in good[1:]:\n    err = fails(mi_getmaterial, name)\n    check(err is None, name + \': \' + str(err))\nlast = None\nfor name in bad:\n    last = fails(mi_getmaterial, name)\n    check(last is not None and "Couldn\'t load" in last and \'from the materials library\' in last, name + \' loaded\')\nraw = callfemm(\'mi_getmaterial("Air")\')\nmi_saveas(\'/tmp/getmaterial.fem\')\ns = open(\'/tmp/getmaterial.fem\').read()\nnair = s.count(\'<BlockName> = "Air"\')\nfor name in good:\n    check(\'<BlockName> = "\' + name + \'"\' in s, name + \' missing from the .fem\')\ncheck(nair == 2, \'Air blocks \' + str(nair))\ncheck(first is None and raw == [], \'return values \' + repr(first) + \', raw reply \' + repr(raw))\ndef field(name, key):\n    part = s[s.find(\'<BlockName> = "\' + name + \'"\'):]\n    return float(re.search(\'<\' + key + r\'> = (\\S+)\', part).group(1))\ncheck(field(\'N42\', \'BHPoints\') == 0 and near(field(\'N42\', \'Mu_x\'), 1.05, 1e-9) and near(field(\'N42\', \'H_c\'), 994529, 1e-9) and near(field(\'N42\', \'Sigma\'), 0.667, 1e-9), \'N42 data\')\nfor name in (\'M-19 14 mil\', \'M-27 14 mil\', \'M-36 14 mil\'):\n    check(field(name, \'BHPoints\') == 61 and near(field(name, \'d_lam\'), 0.3556, 1e-9) and near(field(name, \'LamFill\'), 0.955, 1e-9) and field(name, \'Sigma\') > 1, name + \' data\')\nfor name in (\'N48\', \'N52\', \'Ceramic 8A\', \'Y30\', \'Cast Alnico 5 (LNG37)\'):\n    check(field(name, \'BHPoints\') > 0, name + \' has no B-H curve\')\nreturn str(len(good)) + \' library names loaded; \' + str(len(bad)) + \' refused (\' + \', \'.join(bad) + \'), the last with: \' + last + \'; mi_getmaterial returned None and the raw reply was []; "Air" twice -> \' + str(nair) + \' Air blocks; N42 linear, mu 1.05, H_c 994529 A/m, sigma 0.667 MS/m; M-19/27/36 14 mil: 61 B-H points, d_lam 0.3556 mm, fill 0.955; N48, N52, Ceramic 8A, Y30 and Cast Alnico 5 carry B-H curves\'')
