run('mi_makeABC', 'blank()\nmi_drawrectangle(-5, -5, 5, 5)\nmi_makeABC()\na = mi_getboundingbox()\nrdef = 0.75 * math.sqrt(200)\ncheck(near(a[1], 1.1 * rdef, 1e-6) and near(a[0], -1.1 * rdef, 1e-6), \'default: box \' + show(*a) + \', expected +-\' + str(1.1 * rdef))\ndef counts(name):\n    mi_saveas(\'/tmp/\' + name + \'.fem\')\n    text = open(\'/tmp/\' + name + \'.fem\').read()\n    nmat = re.search(r\'\\[BlockProps\\]\\s*=\\s*(\\d+)\', text).group(1)\n    nbd = re.search(r\'\\[BdryProps\\]\\s*=\\s*(\\d+)\', text).group(1)\n    return nmat, nbd, \'"A=0"\' in text, \'"u7"\' in text\nc0 = counts(\'b_abc0\')\ncheck(c0 == (\'8\', \'2\', True, True), \'default: \' + show(*c0))\nmi_close()\nblank()\nmi_drawrectangle(-5, -5, 5, 5)\nmi_makeABC(2, 20, 0, 0, 1)\nc = mi_getboundingbox()\nc1 = counts(\'b_abc1\')\ncheck(near(c[1], 22) and c1[:3] == (\'3\', \'1\', False), \'n = 2, R = 20, Neumann: \' + show(c[1], *c1))\nmi_close()\ndef pair():\n    blank()\n    mi_addmaterial(\'Copper\', 1, 1, 0, 0, 58, 0, 0, 1, 0, 0, 0, 1, 0)\n    mi_addcircprop(\'P\', 100, 1)\n    mi_addcircprop(\'N\', -100, 1)\n    mi_drawrectangle(1.5, -0.5, 2.5, 0.5)\n    mi_drawrectangle(-2.5, -0.5, -1.5, 0.5)\n    label(2, 0, \'Copper\', \'P\', 1, 0, 0.1)\n    label(-2, 0, \'Copper\', \'N\', 1, 0, 0.1)\n    label(5, 10, \'Air\', None, 0, 0, 0.5)\npair()\nmi_makeABC(7, 20, 0, 0, 0)\nsolve(\'b_abc\')\nby = mo_getpointvalues(0, 8)[2]\nmo_close()\nmi_close()\npair()\ncircle(22, 1)\narcprop(0, 22, 1, \'A0\')\narcprop(0, -22, 1, \'A0\')\nsolve(\'b_abcplain\')\nby2 = mo_getpointvalues(0, 8)[2]\nmo_close()\nfree = -4 / 68 * 1000 * 4e-7 * math.pi * 100 / (2 * math.pi)\neabc, eplain = by / free - 1, by2 / free - 1\ncheck(abs(eabc) < 0.03 and abs(eplain) > 0.05, \'By at (0,8): ABC %.5g, plain %.5g, free %.5g T\' % (by, by2, free))\nreturn \'defaults round a 10 mm square: outer edge at %.4g = 1.1 x 0.75 x diagonal, materials u1..u7, boundary A=0; bc 1 adds no boundary; +-100 A pair, By at (0,8): ABC (n 7, R 20) %.5g T, plain A=0 circle r 22 %.5g T, free space %.5g T (errors %.2f%% and %.1f%%)\' % (a[1], by, by2, free, 100 * eabc, 100 * eplain)')
run('mi_modifyboundprop', 'blank()\ncircle(40, 5)\narcprop(0, 40, 5, \'A0\')\narcprop(0, -40, 5, \'A0\')\nlabel(20, 20, \'Air\')\nmi_modifyboundprop(\'A0\', 2, -0.001)\nunknown = fails(mi_modifyboundprop, \'NoSuch\', 2, 5)\nsolve(\'modifyboundprop\')\nb = mo_getpointvalues(0, 0)\na20 = mo_getpointvalues(20, 0)[0]\nmo_close()\nmi_modifyboundprop(\'A0\', 0, \'Outer\')\nsolve(\'renameboundprop\')\nr = mo_getpointvalues(0, 0)\nmo_close()\ns = open(\'/tmp/renameboundprop.fem\').read()\narcs = \' \'.join(re.search(r\'\\[NumArcSegments\\]\\s*=\\s*\\d+\\s+([^\\[]*)\', s).group(1).split())\ncheck(abs(b[2] - 1) < 1e-3 and abs(b[1]) < 1e-3, \'B \' + show(b[1], b[2]))\ncheck(near(a20, -0.02, 1e-3), \'A(20, 0) \' + str(a20))\ncheck(unknown is None, \'unknown name: \' + str(unknown))\ncheck(\'<BdryName> = "Outer"\' in s and abs(r[1]) < 1e-9 and abs(r[2]) < 1e-9, \'after renaming: B \' + show(r[1], r[2]) + \'; arcs \' + arcs)\nreturn \'A0 with propnum 2 (A1) = -0.001: B at the centre = (%.3g, %.6g) T, A(20, 0) = %.5g Wb/m; renamed to Outer with propnum 0, the arcs lost it (arc lines: %s) and B = (%g, %g) T; an unknown name raised nothing\' % (b[1], b[2], a20, arcs, r[1], r[2])')
run('mi_modifycircprop', "blank()\nmi_addmaterial('Copper', 1, 1, 0, 0, 58, 0, 0, 1, 0, 0, 0, 1, 0)\ncircle(40, 5)\narcprop(0, 40, 5, 'A0')\narcprop(0, -40, 5, 'A0')\nfor x in (-5, 5):\n    mi_drawarc(x + 1, 0, x - 1, 0, 180, 5)\n    mi_drawarc(x - 1, 0, x + 1, 0, 180, 5)\nlabel(0, 20, 'Air')\nmi_addcircprop('C', 10, 1)\nlabel(-5, 0, 'Copper', 'C', 1, 0, 0.3)\nlabel(5, 0, 'Copper', 'C', 1, 0, 0.3)\nmi_modifycircprop('C', 1, 4)\nmi_modifycircprop('C', 2, 0)\nunknown = fails(mi_modifycircprop, 'NoSuch', 1, 5)\nsolve('modifycircprop')\ndef wire(x):\n    mo_selectblock(x, 0)\n    value = mo_blockintegral(7)\n    mo_clearblock()\n    return value\nc1, c2 = wire(-5), wire(5)\ni = mo_getcircuitproperties('C')[0]\nmo_close()\nmi_modifycircprop('C', 0, 'D')\nsolve('renamecircprop')\nr1 = wire(-5)\nd = mo_getcircuitproperties('D')\nmo_close()\ncheck(near(c1, 2, 1e-3) and near(c2, 2, 1e-3) and near(i, 4, 1e-9), 'wires ' + show(c1, c2) + ', circuit ' + str(i))\ncheck(unknown is None, 'unknown name: ' + str(unknown))\ncheck(abs(r1) < 1e-9 and near(d[0], 4, 1e-9), 'after renaming: wire ' + str(r1) + ', D ' + show(*d))\nreturn '10 A series, then propnum 1 = 4 and propnum 2 = 0: wire currents %.5g + %.5g A, circuit current %g A; renamed to D with propnum 0, the wires lost the circuit and carried %g A while D reports %s; an unknown name raised nothing' % (c1, c2, i, r1, show(*d))")
run('mi_modifymaterial', 'fixture_pre()\nmi_modifymaterial(\'Iron\', 1, 300)\nmi_modifymaterial(\'Iron\', 2, 700)\nmi_modifymaterial(\'Iron\', 4, 1)\nmi_modifymaterial(\'Copper\', 5, 29)\nmi_modifymaterial(\'Copper\', 4, 1)\nunknown = fails(mi_modifymaterial, \'NoSuch\', 1, 5)\nbadnum = fails(mi_modifymaterial, \'Iron\', 99, 5)\nsolve(\'modifymaterial\')\nv = mo_getpointvalues(25, 0)\nmo_selectblock(25, 0)\nironI = mo_blockintegral(7)\nmo_clearblock()\nmo_selectblock(0, 0)\nwireI = mo_blockintegral(7)\narea = mo_blockintegral(5)\nmo_clearblock()\ni, volts, flux = mo_getcircuitproperties(\'Iw\')\njs = mo_getpointvalues(0, 0)[8]\nmo_close()\ns = open(\'/tmp/modifymaterial.fem\').read()\ncj = re.search(r\'<J_re> = (\\S+)\', s[s.find(\'<BlockName> = "Copper"\'):]).group(1)\nexpected = (100 - 1e6 * area) * 0.010 / (29e6 * area)\nmi_modifymaterial(\'Iron\', 0, \'Steel\')\nrenamed = fails(mi_analyze, 1)\ncheck(near(v[9], 300, 0.01) and near(v[10], 700, 0.01), \'mu \' + show(v[9], v[10]))\ncheck(near(ironI, 16, 0.01), \'iron block current \' + str(ironI))\ncheck(cj == \'1\' and near(wireI, 100, 1e-3), \'copper J_re \' + cj + \', wire current \' + str(wireI))\ncheck(near(volts, expected, 0.005), \'volts \' + str(volts) + \', expected \' + str(expected))\ncheck(unknown is None and badnum is None, \'unknown name, propnum 99: \' + show(unknown, badnum))\ncheck(renamed is not None and \'2560\' in renamed, \'after renaming Iron: \' + str(renamed))\nreturn \'iron mu %.4g, %.4g; iron J = 1 MA/m^2 -> %.5g A in 16 mm^2; copper sigma 29 MS/m and J 1 MA/m^2 in the 100 A circuit: the wire still carried %.6g A and V = %.5g V = (I - J A) depth / (sigma A) = %.5g V; Js at the wire centre %.6g; Iron renamed with propnum 0: %s; unknown name and propnum 99 raised nothing\' % (v[9], v[10], ironI, wireI, volts, expected, js, renamed)')
